# SIMULATION ONLY. NO API.
# Content for the ESL6 validation cases: the 30 A1-A2 form outcomes of config/agent_sim_esl6/LEARNING_RULES.md section 1b that have
# at least one wrong belief (the 3 GAP outcomes are excluded). Belief texts follow the 1b table; W1/W2 order is the table's.
# Per outcome: C/W/E texts (judge state), RULE (one general rule line that contradicts every wrong belief), CONTRAST (right/wrong pair per Wk),
# SENT (3 own-sentence tasks: prompt, reference correct sentence, erroneous version per Wk), BLANK (3 items: prompt, correct answer, wrong answer per Wk),
# LOOK (a look-hint). Every SENT/BLANK item tests every wrong belief of its outcome (section 4a), so its probes are all of the outcome's Wk.
GAP = ['EN-F-A1-GR-possessive-adjectives', 'EN-F-A1-VO-common-adjectives', 'EN-F-A2-VO-make-do']
TAIL = ' (answer with only the missing word)'
TAILS = ' (write the whole sentence)'


def O(key, oid, sec1, topic, C, W, E, rule, contrast, sent, blank, look):
    ws = ['W1', 'W2'][:len(W)]
    assert len(C) == len(W) == len(E) == len(contrast) and len(sent) == 3 and len(blank) == 3, key
    for _, _, errs in sent + blank: assert sorted(errs) == ws, key
    return {'key': key, 'id': oid, 'sec1': sec1, 'topic': topic, 'ws': ws, 'C': dict(zip(['C1', 'C2'], C)), 'W': dict(zip(ws, W)), 'E': dict(zip(ws, E)),
            'rule': rule, 'contrast': dict(zip(ws, contrast)), 'sent': sent, 'blank': blank, 'look': look}


